function money(value:number){ return "₹" + value.toLocaleString("en-IN"); }
function categoryLabel(category:Category){ return COLLECTIONS.find((c)=>c.id===category)?.title ?? "All bags"; }

function BagArt({base="cream",print="floral",large=false}:{base:"cream"|"black";print:"floral"|"sun"|"type"|"duo"|"custom";large?:boolean}){
  const fill = base === "black" ? "#26231f" : "#eee5d6";
  const ink = base === "black" ? "#e8ddc9" : "#5c4030";
  return (
    <svg viewBox="0 0 320 350" className={large ? "h-full w-full" : "h-full w-full"} role="img" aria-label={base + " canvas tote bag illustration"}>
      <ellipse cx="160" cy="317" rx="104" ry="13" fill="#4e3d2b" opacity=".12"/>
      <path d="M104 116 C104 50 121 24 160 24 C199 24 216 50 216 116" fill="none" stroke={base==="black"?"#312c26":"#d9cdbb"} strokeWidth="17" strokeLinecap="round"/>
      <path d="M104 116 C104 50 121 24 160 24 C199 24 216 50 216 116" fill="none" stroke={base==="black"?"#171513":"#f7f1e7"} strokeWidth="5" strokeLinecap="round" opacity=".65"/>
      <path d="M76 112 Q76 102 89 102 H231 Q244 102 244 115 L256 294 Q257 307 243 307 H77 Q63 307 64 294 Z" fill={fill} stroke={base==="black"?"#171513":"#d8cbb8"} strokeWidth="2"/>
      <path d="M87 122 H233" stroke={base==="black"?"#494138":"#d2c5b2"} strokeWidth="2" opacity=".8"/>
      <path d="M89 118 V296 M231 118 V296" stroke={base==="black"?"#3a342c":"#d5c8b7"} strokeWidth="1.2" opacity=".45"/>
      {print==="floral" && <g fill="none" stroke={ink} strokeWidth="3.3" strokeLinecap="round" strokeLinejoin="round"><path d="M160 270 C158 235 164 200 171 161 C175 142 175 134 171 127"/><path d="M164 225 C137 211 128 189 133 172 C151 178 164 194 164 225Z"/><path d="M166 199 C191 180 199 160 190 143 C173 149 165 169 166 199Z"/><path d="M158 246 C138 236 127 219 130 205 C146 209 157 224 158 246Z"/><path d="M170 173 C151 158 149 139 159 127 C172 138 177 155 170 173Z"/><path d="M173 259 C190 245 204 244 212 254 C204 267 187 271 173 259Z"/><path d="M160 141 C150 132 148 118 159 111 C170 119 172 132 160 141Z"/><path d="M133 173 C120 162 119 149 131 141 C142 151 143 164 133 173Z"/><path d="M190 143 C190 128 201 119 213 126 C213 140 203 149 190 143Z"/></g>}
      {print==="sun" && <g fill="none" stroke={ink} strokeWidth="3" strokeLinecap="round"><circle cx="160" cy="190" r="33"/><path d="M160 134 V147 M160 233 V246 M104 190 H117 M203 190 H216 M120 150 L130 160 M190 220 L200 230 M200 150 L190 160 M130 220 L120 230"/><path d="M138 198 Q160 178 182 198" /></g>}
      {print==="type" && <g fill={ink} textAnchor="middle"><text x="160" y="180" fontFamily="Georgia,serif" fontSize="21" letterSpacing="2">make</text><text x="160" y="205" fontFamily="Georgia,serif" fontSize="21" letterSpacing="2">room</text><path d="M127 220 H193" stroke={ink} strokeWidth="1.5"/></g>}
      {print==="duo" && <g><path d="M160 135 C130 155 126 194 160 242 C194 194 190 155 160 135Z" fill={ink} opacity=".92"/><path d="M160 148 V232" stroke={base==="black"?"#26231f":"#eee5d6"} strokeWidth="2.2"/><circle cx="160" cy="181" r="11" fill={base==="black"?"#26231f":"#eee5d6"}/></g>}
      {print==="custom" && <g fill="none" stroke={ink} strokeWidth="2.8" strokeLinecap="round"><path d="M160 154 C138 128 112 156 133 178 L160 205 L187 178 C208 156 182 128 160 154Z"/><path d="M160 205 V245 M140 226 H180"/><circle cx="160" cy="145" r="4" fill={ink}/></g>}
      <path d="M84 293 Q160 299 236 293" stroke={base==="black"?"#51483e":"#d6c9b6"} strokeWidth="1.5" fill="none"/>
    </svg>
  );
}

function SectionHeading({eyebrow,title,copy}:{eyebrow:string;title:string;copy?:string}){
  return <div className="mb-9 flex flex-col gap-3 md:mb-12 md:flex-row md:items-end md:justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.26em] text-[#91775d]">{eyebrow}</p><h2 className="mt-3 max-w-2xl font-serif text-4xl leading-[1.02] tracking-[-.045em] text-[#2b241e] sm:text-5xl">{title}</h2></div>{copy&&<p className="max-w-sm text-sm leading-6 text-[#75695f]">{copy}</p>}</div>;
}

