        {megaOpen&&<div className="absolute left-0 right-0 top-full hidden border-t border-[#6d5743]/10 bg-[#f7f3ec] px-8 py-7 shadow-[0_18px_32px_rgba(45,32,20,.10)] lg:block"><div className="mx-auto grid max-w-6xl grid-cols-4 gap-4">{COLLECTIONS.map((c)=><button key={c.id} type="button" onClick={()=>chooseCategory(c.id)} className="group rounded-2xl bg-[#eee6db] p-4 text-left transition hover:-translate-y-1 hover:bg-[#e6dacb]"><div className="mb-3 flex h-28 items-center justify-center overflow-hidden rounded-xl bg-[#e4d9ca]"><div className="h-28 w-28 transition duration-500 group-hover:scale-105"><BagArt base={c.art} print={c.print}/></div></div><p className="font-serif text-xl">{c.title}</p><p className="mt-1 text-xs text-[#847467]">{c.line}</p></button>)}</div></div>}
